(3151008, 442272, 70124, '<td valign="top">That''s one wild shot. What a setup.</td>', 'That''s one wild shot. What a setup.', '2006-12-26 23:23:19.000000', NULL, 1),
(3151009, 441653, 16197, '<td valign="top">The dof is fun in this image.  Yet, Im not sure if I care for the placement of it.  it is a nice image, yet does not give me the full feel for legal or editor.</td>', 'The dof is fun in this image.  Yet, Im not sure if I care for the placement of it.  it is a nice image, yet does not give me the full feel for legal or editor.', '2006-12-26 23:24:12.000000', NULL, 1),
