INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3153310, 441087, 66384, '<td valign="top">This is a really nice composition and a great contrast between the cheerful, bright Christmas decorations and the miserable man in the shadows. On my monitor it is very difficult to see the man. I would like to have him lightened ever so slightly. Perhaps he is on your monitor. This is one of the difficult things about displaying photography on the web. The other thing is I''m not sure what occupation or passtime this represents -- unemployment? 8</td>', 'This is a really nice composition and a great contrast between the cheerful, bright Christmas decorations and the miserable man in the shadows. On my monitor it is very difficult to see the man. I would like to have him lightened ever so slightly. Perhaps he is on your monitor. This is one of the difficult things about displaying photography on the web. The other thing is I''m not sure what occupation or passtime this represents -- unemployment? 8', '2006-12-27 11:39:52.000000', NULL, 1),
(3153313, 442308, 56461, '<td valign="top">This is great!</td>', 'This is great!', '2006-12-27 11:41:16.000000', NULL, 1),
(3153318, 441891, 66384, '<td valign="top">And a mighty cute little seedling you have there.</td>', 'And a mighty cute little seedling you have there.', '2006-12-27 11:42:28.000000', NULL, 1),
(3153329, 441477, 66384, '<td valign="top">Nice composition, but not much in focus here. I''m sure this is the way you intended it, but it''s a bit of a strain trying to view it. The ESC key seems to be the focal point, which is interesting, but even that is not clear.</td>', 'Nice composition, but not much in focus here. I''m sure this is the way you intended it, but it''s a bit of a strain trying to view it. The ESC key seems to be the focal point, which is interesting, but even that is not clear.', '2006-12-27 11:48:53.000000', NULL, 1),
(3153352, 441577, 25678, '<td valign="top">I''m not voting on this challenge, but I wanted to comment on your picture.<br/> <br/>I love this shot!  Nice perspective.  My only comment would be to have shot the picture in a more ''natural'' setting: running water, field, forest, or something along those lines.  I have a feeling this will be under-rated as it doesn''t have that DPC ''look,'' but I wanted to let you know that I like it!<br/> <br/>I''m getting my degree in biology and hoping to place part of the emphasis on conservation.  We should talk ;)</td>', 'I''m not voting on this challenge, but I wanted to comment on your picture. I love this shot!  Nice perspective.  My only comment would be to have shot the picture in a more ''natural'' setting: running water, field, forest, or something along those lines.  I have a feeling this will be under-rated as it doesn''t have that DPC ''look,'' but I wanted to let you know that I like it! I''m getting my degree in biology and hoping to place part of the emphasis on conservation.  We should talk ;)', '2006-12-27 11:59:48.000000', NULL, 1),
(3153480, 441734, 34763, '<td valign="top">well done, touching</td>', 'well done, touching', '2006-12-27 12:40:41.000000', NULL, 1),
