(3163699, 441223, 55767, '<td valign="top">in my opinion, this is the best of them all! kudos to you!!</td>', 'in my opinion, this is the best of them all! kudos to you!!', '2006-12-31 00:58:48.000000', NULL, 1),
(3163708, 441577, 4767, '<td valign="top">What a cleverly conceived image!</td>', 'What a cleverly conceived image!', '2006-12-31 01:01:49.000000', NULL, 1),
(3163716, 441358, 4767, '<td valign="top">Oh my oh my...  why does this remind me of... vegemite?  No, I mean... a place where a woman is called a Sheila?  If this isn''t a Sherpet image, you owe her royalties, you emulator, you!  (May I tell you how much I like this image?  In every way I can think of, it works.)  And if you are NOT Sherpet, what a nice tribute/complement to her.  It is worthy of her best work.</td>', 'Oh my oh my...  why does this remind me of... vegemite?  No, I mean... a place where a woman is called a Sheila?  If this isn''t a Sherpet image, you owe her royalties, you emulator, you!  (May I tell you how much I like this image?  In every way I can think of, it works.)  And if you are NOT Sherpet, what a nice tribute/complement to her.  It is worthy of her best work.', '2006-12-31 01:05:09.000000', NULL, 1),
(3163729, 441653, 4767, '<td valign="top">I''m sorry, I really think the frame detracts from this photo.  The book on top frames it well, the colored markers and the silvery pens frame the upper right, the second page intruding from the left bottom  establishes boundaries there...  the frame seems to be an unfortunate redundancy to me.</td>', 'I''m sorry, I really think the frame detracts from this photo.  The book on top frames it well, the colored markers and the silvery pens frame the upper right, the second page intruding from the left bottom  establishes boundaries there...  the frame seems to be an unfortunate redundancy to me.', '2006-12-31 01:14:19.000000', NULL, 1),
(3163735, 441276, 4767, '<td valign="top">For an elementary school kid, he looks decidedly menacing.  I''d suggest a slightly different reading curriculum, Becky.</td>', 'For an elementary school kid, he looks decidedly menacing.  I''d suggest a slightly different reading curriculum, Becky.', '2006-12-31 01:16:35.000000', NULL, 1),
(3163739, 441675, 4767, '<td valign="top">How seasonal!  I''d have preferred to see the letters in focus and the Santa''s helper accoutrements out, but that''s just my preference.</td>', 'How seasonal!  I''d have preferred to see the letters in focus and the Santa''s helper accoutrements out, but that''s just my preference.', '2006-12-31 01:18:02.000000', NULL, 1),
