(3163822, 441673, 66515, '<td valign="top">This is interesting but I am not sure what to think of the borders. They kinda "squish" the picture a bit.</td>', 'This is interesting but I am not sure what to think of the borders. They kinda "squish" the picture a bit.', '2006-12-31 02:16:30.000000', NULL, 1),
(3163823, 440036, 66515, '<td valign="top">Too small and too dark.</td>', 'Too small and too dark.', '2006-12-31 02:16:43.000000', NULL, 1),
(3163824, 442328, 66515, '<td valign="top">The connection between the Emmy and your occupation isn''t obvious to me. Does this mean that you are an actor? Do you craft the Emmy''s? I might be just a little slow but I need a little help here.</td>', 'The connection between the Emmy and your occupation isn''t obvious to me. Does this mean that you are an actor? Do you craft the Emmy''s? I might be just a little slow but I need a little help here.', '2006-12-31 02:18:24.000000', NULL, 1),
