INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3165474, 441397, 29904, '<td valign="top">I know these things are hard to set up and get everyone cooperating, nice job!  Nice composition, glad it''d in B&amp;W, makes it less busy.</td>', 'I know these things are hard to set up and get everyone cooperating, nice job!  Nice composition, glad it''d in B&W, makes it less busy.', '2006-12-31 22:24:39.000000', NULL, 1),
(3165477, 441223, 29904, '<td valign="top">Jeez this looks hard!  perfect execution and great idea!</td>', 'Jeez this looks hard!  perfect execution and great idea!', '2006-12-31 22:26:39.000000', NULL, 1),
(3165482, 441577, 29904, '<td valign="top">Lovely setup, clearity, dof, and excellent idea to portray what you do!</td>', 'Lovely setup, clearity, dof, and excellent idea to portray what you do!', '2006-12-31 22:28:46.000000', NULL, 1),
(3165486, 442270, 29904, '<td valign="top">Nicely executed, like the softness.</td>', 'Nicely executed, like the softness.', '2006-12-31 22:31:28.000000', NULL, 1),
