(3166282, 440765, 61818, '<td valign="top">I liked this one a lot.  I bet you could sell this as a stock photo.</td>', 'I liked this one a lot.  I bet you could sell this as a stock photo.', '2007-01-01 02:17:23.000000', NULL, 0),
(3166284, 441713, 61818, '<td valign="top">Loved this entry.  Well done and nice score.</td>', 'Loved this entry.  Well done and nice score.', '2007-01-01 02:18:07.000000', NULL, 0),
(3166285, 441787, 66384, '<td valign="top">Well, you called it. The public-at-large doesn''t care for abstracts. But I do, and I gave it a 9. Sorry about your final score, this deserved better.</td>', 'Well, you called it. The public-at-large doesn''t care for abstracts. But I do, and I gave it a 9. Sorry about your final score, this deserved better.', '2007-01-01 02:18:35.000000', NULL, 0),
(3166292, 441087, 61818, '<td valign="top">I had no idea what in the world this shot was trying to convey.  Reading your description, I assume you are occupied with fighting off depression or something?  Alright, a clever challenge entry in concept but damned hard to illustrate in a photo as I think your unfortunate placing confirms.  Good to see you think outside of the box though, looking forward to your future entries to see what you come up with.</td>', 'I had no idea what in the world this shot was trying to convey.  Reading your description, I assume you are occupied with fighting off depression or something?  Alright, a clever challenge entry in concept but damned hard to illustrate in a photo as I think your unfortunate placing confirms.  Good to see you think outside of the box though, looking forward to your future entries to see what you come up with.', '2007-01-01 02:23:21.000000', NULL, 0),
(3166300, 442330, 60862, '<td valign="top">Congrats on the very personal, meaningful shot and the ribbon! :)</td>', 'Congrats on the very personal, meaningful shot and the ribbon! :)', '2007-01-01 02:27:42.000000', NULL, 0),
