INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3166882, 442001, 55838, '<td valign="top">I love this image.  So cold and contrasty - I even like the white sky.  A nice different looking waterfall shot.  Congratulations on top 20.  Adding to favorites.</td>', 'I love this image.  So cold and contrasty - I even like the white sky.  A nice different looking waterfall shot.  Congratulations on top 20.  Adding to favorites.', '2007-01-01 08:19:02.000000', NULL, 0),
(3166887, 442223, 55838, '<td valign="top">I''ll never call you boring!  I think it was wise to add the subtitle - probably not every country calls accountants "bean counters" and (speaking from the voice of experience) DNMC votes &amp; comments are not fun at all - especially when you completely meet the challenge.  This shot is well done.  Congratulations on top 20 and a new PB!</td>', 'I''ll never call you boring!  I think it was wise to add the subtitle - probably not every country calls accountants "bean counters" and (speaking from the voice of experience) DNMC votes & comments are not fun at all - especially when you completely meet the challenge.  This shot is well done.  Congratulations on top 20 and a new PB!', '2007-01-01 08:23:11.000000', NULL, 0),
(3166891, 440765, 55838, '<td valign="top">Love this shot - clean and nicely done.  It would not have been nearly as effective without the blown out sky in my opinion.  Good choice.  Congratulations on top 20!</td>', 'Love this shot - clean and nicely done.  It would not have been nearly as effective without the blown out sky in my opinion.  Good choice.  Congratulations on top 20!', '2007-01-01 08:26:10.000000', NULL, 0),
